/** Renders integer cents as dollars (see SPEC.md). */
export function formatCents(cents: number): string {
	const negative = cents < 0;
	const abs = Math.abs(cents);
	const dollars = Math.floor(abs / 100);
	const rest = String(abs % 100).padStart(2, '0');
	return (negative ? '-' : '') + '$' + dollars + '.' + rest;
}

export function formatReceipt(lines: Array<{ label: string; cents: number }>): string {
	const parts = lines.map((line) => line.label + ': ' + formatCents(line.cents));
	const sum = lines.reduce((total, line) => total + line.cents, 0);
	parts.push('Total: ' + formatCents(sum));
	return parts.join('\n');
}
```

`formatCents` now formats the absolute amount with two cent digits and puts the minus sign before `$`, and `formatReceipt` always uses that result for the total, including the empty list.
